#define res iResolution
#define mous iMouse
#define time iTime

//radPosAt and ratPosAt in Common tab
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2.0 - vec2(res.x,res.y)) / 
                min(res.x, res.y - 10.0);

    float prev_render_time = texelFetch(iChannel0, ivec2(0), 0).x;

    // Background color
    vec3 color = vec3(0.1);

    // Draw axes
    float axisWidth = 0.004;
    color = mix(color, vec3(0.5), 
            float(abs(uv.x) < axisWidth) + float(abs(uv.y) < axisWidth));

    // Draw unit circle
    float circleWidth = 0.01;
    float radius = abs(length(uv) - 1.0);
    float blur   = 3.0 / min(res.x, res.y);
    float edge   = smoothstep(circleWidth + blur, circleWidth - blur, radius);
    color = mix(color, vec3(0.8), edge);

    // Compute position
    float quadrantCount = 4.0; // # of quadrants for path
    float speed = (4./quadrantCount) * 0.25; // based on one period/full cycle

    // If paused or clicked, use mouse, else use iTime
    float t = mix(
              mix(fract(time * speed), fract(mous.x / res.x), (prev_render_time == time)), 
              fract(mous.x / res.x), 
              mous.w > 0.0 || mous.z > 0.0);

    // Variable velocity
    float variable = fract(t * quadrantCount);
    vec2  pos_rad  = radPosAt(variable, t * quadrantCount); //Radical
    vec2  pos_rat  = ratPosAt(variable, t * quadrantCount); //Rational

    // Constant velocity (Using tan ratio for angular/constant vel)
    float constant = toAngle(t * quadrantCount);
    vec2 pos_const = radPosAt(constant, t * quadrantCount); //Traditional

    // Draw points - starting at alternate positions
    float pointSize = 0.06;
    // Clockwise when y-coordinate is negative
    color = mix(color, vec3(0.0, 0.0, 1.0),//blue
        smoothstep(pointSize, 0.0, length(uv - rot90(vec2(pos_rad.x,-pos_rad.y)))));
    color = mix(color, vec3(1.0, 0.0, 0.0),//red
        smoothstep(pointSize, 0.0, length(uv - rot180(vec2(pos_rat.x,-pos_rat.y)))));
    color = mix(color, vec3(0.9, 0.5, 1.0),//magenta
        smoothstep(pointSize, 0.0, length(uv - rot270(vec2(pos_const.x,-pos_const.y)))));

    // Draw center-left point
    color = mix(color, vec3(0.0, 1.0, 0.0), 
        smoothstep(pointSize, 0.0, length(uv - mix(vec2(-1.82, 0.0), 
                                                   vec2(-1.0,  0.0), t))));   

    fragColor = vec4(color, 1.0);
}

