#define HALFPI 1.57079632679489661923
#define TAU (HALFPI*4.0)

//helper for the traditional arc length
float toAngle(float t) {
    float frac = t - floor(t);  // equivalent to fract(t)
    return tan(frac * HALFPI)/(1.0 + tan(frac * HALFPI));
}

// Radical sine approximation (optimized)
float rsin(float x) {
    float a = 1.0 - 2.0 * x + 2.0 * x * x;
    float invSqrtA = inversesqrt(a);
    return x * invSqrtA;
}

// Radical cosine approximation (optimized)
float rcos(float x) {
    float a = 1.0 - 2.0 * x + 2.0 * x * x;
    float invSqrtA = inversesqrt(a);
    return (1.0 - x) * invSqrtA;
}

// Rational sine approximation (optimized)
float rpsin(float x) {
    float x2 = x * x;
    return (2.0 * x) / (1.0 + x2);
}

// Rational cosine approximation (optimized)
float rpcos(float x) {
    float x2 = x * x;
    return (1.0 - x2) / (1.0 + x2);
}

// Quadrant logic (branchless)
vec2 getQuadrant(int quadrant, float c, float s) {
    /*   -x,+y  |  +x,+y
        ___q2___|___q3____
         -x,-y  |  +x,-y
           q1   |    q0    */

    // 1 if even, 0 if odd
    float qEven = 1.0 - float(quadrant & 1);
    // 1 if first two quadrants, 0 otherwise
    float qFirstHalf = 1.0 - float(quadrant >= 2);

    // Swap c and s based on quadrant parity
    float x = mix(s, c, qEven);
    float y = mix(c, s, qEven);

    // Flip y for upper/lower halves
    y *= mix(-1.0, 1.0, qFirstHalf);
    // Flip x for left/right halves
    x *= mix(-1.0, 1.0, float(quadrant == 0 || quadrant == 3)); 

    return vec2(x, y);
}

// Optimized radical-based trig position
vec2 radPosAt(float param, float quadrantCount) {
    int quadrant = int(mod(quadrantCount, 4.0));
    return getQuadrant(quadrant, rcos(param), rsin(param));
}

// Optimized rational-based trig position
vec2 ratPosAt(float param, float quadrantCount) {
    int quadrant = int(mod(quadrantCount, 4.0));
    return getQuadrant(quadrant, rpcos(param), rpsin(param));
}

vec2 debug(float q, float c, float s) {
    if(q < 0.25) return vec2(c, -s);
    else if(q < 0.5) return vec2(-s, -c);
    else if(q < 0.75) return vec2(-c, s);
    else return vec2(s, c);
}

vec2 rot90(vec2 v) {
    return vec2(mat2(0.0,-1.0,1.0,0.0) * v);
}

vec2 rot180(vec2 v) {
    return vec2(mat2(-1.0,0.0,0.0,-1.0) * v);
}

vec2 rot270(vec2 v) {
    return vec2(mat2(0.0,1.0,-1.0,0.0) * v);
}
